#include "htmlui/compat/ua/UserAgentStyle.h"

#include "htmlui/compat/Hash.h"
#include "htmlui/compat/RmlLogTranslator.h"
#include "htmlui/compat/SourceFiles.h"
#include "htmlui/compat/VirtualFiles.h"
#include "htmlui/compat/css/CssRewriter.h"

#include "Log.h"

// generated by embed_ua.cmake (CMake builds) or written by the Apple export; a stand-in with
// no files in engine/shaders otherwise
#include "htmlui_ua.h"

#include <cstring>
#include <map>
#include <mutex>

using namespace jasperengine;
using namespace jasperengine::htmlui::compat;

namespace {

    constexpr const char* kStylesheetName = "useragent.css";

    struct Cache {
        std::mutex mutex;
        std::map<uint64_t, std::shared_ptr<const UserAgentStyle::Sheet>> sheets;
        std::map<uint64_t, uint64_t> translatorHandles;
        bool missingReported = false;
    };

    Cache& cache(){
        static Cache instance;
        return instance;
    }

    std::vector<UserAgentStyle::EmbeddedFile> collectEmbedded(){
        std::vector<UserAgentStyle::EmbeddedFile> files;
        for (size_t i = 0; i < embedded::uaFileCount; i++){
            const embedded::UaFile& file = embedded::uaFiles[i];
            if (file.name)
                files.push_back(UserAgentStyle::EmbeddedFile{file.name, file.data, file.size});
        }
        return files;
    }

    const std::vector<UserAgentStyle::EmbeddedFile>& embeddedList(){
        static const std::vector<UserAgentStyle::EmbeddedFile> files = collectEmbedded();
        return files;
    }

}

Span<const UserAgentStyle::EmbeddedFile> UserAgentStyle::embeddedFiles(){
    const std::vector<EmbeddedFile>& files = embeddedList();
    return Span<const EmbeddedFile>(files.data(), files.size());
}

std::string_view UserAgentStyle::source(){
    for (const EmbeddedFile& file : embeddedList()){
        if (std::strcmp(file.name, kStylesheetName) == 0)
            return std::string_view(reinterpret_cast<const char*>(file.data), file.size);
    }
    return std::string_view();
}

std::string UserAgentStyle::virtualPath(const ForkFeatures& fork){
    if (fork == ForkFeatures::present())
        return std::string(VirtualFiles::kPrefix) + "ua.rcss";
    return std::string(VirtualFiles::kPrefix) + "ua-" + toHex(fork.bits(), 8) + ".rcss";
}

std::shared_ptr<const UserAgentStyle::Sheet> UserAgentStyle::get(const ForkFeatures& fork){
    Cache& c = cache();
    std::lock_guard<std::mutex> lock(c.mutex);
    const auto found = c.sheets.find(fork.bits());
    if (found != c.sheets.end())
        return found->second;

    const std::string_view text = source();
    if (text.empty() && !c.missingReported){
        c.missingReported = true;
        Log::warn("[HTML UI] the user-agent stylesheet is not embedded in this build; documents get no default styles");
    }

    auto files = std::make_shared<SourceFiles>();
    const uint32_t file = files->add(kSourcePath, std::string(text));

    auto sheet = std::make_shared<Sheet>();
    sheet->fork = fork;
    sheet->virtualPath = virtualPath(fork);
    {
        CompatOptions options;
        options.fork = fork;
        DiagnosticSink sink(*files);
        CssRewriter rewriter(options, *files, sink);
        StylesheetInput input;
        input.kind = StylesheetInput::Kind::UserAgent;
        input.file = file;
        input.text = files->text(file);
        RewriteResult result = rewriter.rewrite(Span<const StylesheetInput>(&input, 1));
        if (!result.sheets.empty()){
            sheet->rcss = std::move(result.sheets[0].rcss);
            sheet->lines = std::move(result.sheets[0].lines);
        }
        sheet->diagnostics = sink.take();
        for (Diagnostic& diagnostic : sheet->diagnostics){
            if (diagnostic.origin.empty())
                diagnostic.origin = "user-agent stylesheet";
        }
    }
    sheet->files = files;

    VirtualFiles::add(sheet->virtualPath, sheet->rcss, 0);

    RmlLogTranslator::Registration registration;
    registration.owner = sheet;
    registration.files = sheet->files.get();
    registration.mappings.push_back(RmlLogTranslator::LineMapping{sheet->virtualPath, 1, &sheet->lines.lines});
    c.translatorHandles[fork.bits()] = RmlLogTranslator::add(std::move(registration));

    c.sheets.emplace(fork.bits(), sheet);
    return sheet;
}

void UserAgentStyle::registerInternalFiles(){
    for (const EmbeddedFile& file : embeddedList()){
        if (std::strcmp(file.name, kStylesheetName) == 0)
            continue;
        const std::string path = std::string(VirtualFiles::kPrefix) + "ua/" + file.name;
        if (!VirtualFiles::exists(path))
            VirtualFiles::add(path, std::string(reinterpret_cast<const char*>(file.data), file.size), 0);
    }
}

void UserAgentStyle::clearCache(){
    Cache& c = cache();
    std::lock_guard<std::mutex> lock(c.mutex);
    for (const auto& entry : c.sheets)
        VirtualFiles::remove(entry.second->virtualPath);
    for (const auto& handle : c.translatorHandles)
        RmlLogTranslator::remove(handle.second);
    c.sheets.clear();
    c.translatorHandles.clear();
}

std::string UserAgentStyle::buildEmbeddedHeader(Span<const EmbeddedFile> files){
    static const char* hex = "0123456789abcdef";
    std::string content = "// Generated from engine/core/htmlui/compat/ua. Do not edit.\n\n";
    content += "#pragma once\n\n#include <cstddef>\n\n";
    content += "namespace jasperengine { namespace htmlui { namespace compat { namespace embedded {\n\n";
    content += "struct UaFile { const char* name; const unsigned char* data; size_t size; };\n\n";

    std::string table;
    size_t index = 0;
    for (const EmbeddedFile& file : files){
        content += "static const unsigned char uaFile" + std::to_string(index) + "[] = {";
        for (size_t i = 0; i < file.size; i++){
            const unsigned char byte = file.data[i];
            content += "0x";
            content += hex[byte >> 4];
            content += hex[byte & 0xF];
            content += ',';
        }
        content += "0x00};\n\n";
        table += "    { \"" + std::string(file.name) + "\", uaFile" + std::to_string(index) + ", " + std::to_string(file.size) + " },\n";
        index++;
    }

    if (index == 0)
        content += "static const UaFile uaFiles[1] = { { nullptr, nullptr, 0 } };\n";
    else
        content += "static const UaFile uaFiles[] = {\n" + table + "};\n";
    content += "static const size_t uaFileCount = " + std::to_string(index) + ";\n\n} } } }\n";
    return content;
}

std::string UserAgentStyle::buildEmbeddedHeader(){
    return buildEmbeddedHeader(embeddedFiles());
}
